properties.query:
let timeframe = ago(1h);
let LinDevices = DeviceInfo
| where Timestamp >=timeframe
//Extracting only Linux Machines
| where OSPlatform == "Linux"
| distinct DeviceId;
DeviceProcessEvents
| join kind=fullouter  LinDevices on $left.DeviceId == $right.DeviceId
| where Timestamp >= timeframe
| where FileName contains "curl" and ProcessCommandLine has_any (@"-x", @"socks4a://", "socks5", "socks4", @"--preproxy", @"--proxy")
